int n=0;void Check(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS: "+s);}void Reject(Action a,string s){try{a();}catch{Check(true,s);return;}throw new Exception("Accepted: "+s);}
var date=new DateTimeOffset(2026,10,26,12,0,0,TimeSpan.Zero);var calendar=new HistoryCalendar<DateTimeOffset>([date,date.AddDays(-1)],x=>x,2026);Check(calendar.Years.SequenceEqual(new[]{2026}),"Calendar exposes one year root");Check(HistoryCalendar<DateTimeOffset>.Months().SequenceEqual(Enumerable.Range(1,12)),"Every year exposes all 12 months");Check(HistoryCalendar<DateTimeOffset>.Days(2026,4).Length==30,"April has 30 expandable days");Check(HistoryCalendar<DateTimeOffset>.Days(2026,2).Length==28,"February normal year has 28 days");Check(HistoryCalendar<DateTimeOffset>.Days(2024,2).Length==29,"Leap year has 29 days");Check(calendar.Count(2026,10)==2&&calendar.Items(2026,10,1).Count==0,"Calendar retains empty day groups and counts media");Check(new HistoryCalendar<DateTimeOffset>([],x=>x,2026).Years.Single()==2026,"Empty library retains current year calendar");
var cache=new BudgetCache<string,string>(10,2);cache.Add("a","A",4);cache.Add("b","B",4);Check(cache.TryGet("a",out var a)&&a=="A","Cache returns and promotes hit");var removed=cache.Add("c","C",4);Check(removed.SequenceEqual(new[]{"B"})&&!cache.TryGet("b",out _),"Least recent entry evicted by count/bytes");cache.Add("large","X",11);Check(cache.Stats.Bytes<=10&&cache.Stats.Count==2,"Oversized entry bypasses budget");cache.Clear();Check(cache.Stats.Bytes==0&&cache.Stats.Count==0,"Cache clear releases tracked memory");Parallel.For(0,1000,i=>{cache.Add(i.ToString(),"value",3);cache.TryGet(i.ToString(),out _);});Check(cache.Stats.Bytes<=10&&cache.Stats.Count<=2,"Concurrent cache operations remain bounded");
var view=new PixelRect(0,0,120,80);var legacy=new ImageAppearance{CanvasWidth=440,CanvasHeight=400};Check(CanvasEditing.SourceBounds(view,legacy)==view,"Old canvas never opts into expanded annotation bounds");var expanded=CanvasEditing.Expand(view,new());Check(expanded.DrawOutsideImage&&expanded.CanvasWidth==440&&expanded.CanvasHeight==400,"Canvas expands explicitly by160 per edge");Check(CanvasEditing.SourceBounds(view,expanded)==new PixelRect(-160,-160,440,400),"Negative source coordinates represent area outside bitmap");var layout=new ImageLayout(view,expanded);Check(layout.ToOutput(0,0)==new ImagePoint(160,160)&&layout.ImageWidth==120&&layout.ImageHeight==80,"Original pixel extent and scale preserved after extension");
var doc=new EditorDocument{OriginalWidth=120,OriginalHeight=80,SourceHash="hash",Appearance=expanded,Annotations=[new(){Kind=AnnotationKind.Rectangle,X1=-120,Y1=-80,X2=-40,Y2=-10}]};doc.Validate(120,80,"hash");Check(doc.Version==13,"Outside-canvas document uses protected schema13");var copy=EditorDocument.Deserialize(doc.Serialize());copy.Validate(120,80,"hash");Check(copy.Version==13&&copy.Appearance.DrawOutsideImage&&copy.Annotations[0].X1==-120,"Schema13 round trip keeps negative annotation coordinates");var old=new EditorDocument{OriginalWidth=120,OriginalHeight=80};old.Validate(120,80,"");Check(old.Version==12&&!old.Serialize().Contains("DrawOutsideImage"),"Unchanged legacy documents retain schema12 bytes/semantics");var future=new EditorDocument{OriginalWidth=120,OriginalHeight=80,Version=14};Reject(()=>future.Validate(120,80,""),"Future schema14 rejected");var session=new EditorSession(new(){OriginalWidth=120,OriginalHeight=80});session.Change(d=>d.Appearance=CanvasEditing.Expand(d.Viewport,d.Appearance));session.Undo();Check(!session.Document.Appearance.DrawOutsideImage&&session.Document.Appearance.CanvasWidth==0,"One Undo returns original canvas");session.Redo();Check(session.Document.Appearance.CanvasWidth==440,"Redo restores canvas recipe");
for(int turn=0;turn<4;turn++)for(int flip=0;flip<2;flip++){var style=CanvasEditing.Expand(view,new(){QuarterTurns=turn,FlipHorizontal=flip==1});var bounds=CanvasEditing.SourceBounds(view,style);Check(bounds.X<0&&bounds.Y<0&&bounds.Right>view.Right&&bounds.Bottom>view.Bottom,"Outside bounds survive rotation/flip "+turn+"/"+flip);}
string root=Path.Combine(Path.GetTempPath(),"Captovix-release-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string path=Path.Combine(root,"doc.json");EditorDocument Validate(string text){var d=EditorDocument.Deserialize(text);d.Validate(120,80,"hash");return d;}File.WriteAllText(path,doc.Serialize());RecoveryFiles.Backup(path,Validate);var original=File.ReadAllBytes(path);Check(File.ReadAllBytes(RecoveryFiles.BackupPath(path)).SequenceEqual(original),"Last-good backup preserves exact prior bytes");File.WriteAllText(path,"broken");var recovered=RecoveryFiles.Load(path,Validate,out bool fallback);Check(fallback&&recovered.Version==13&&File.ReadAllText(path)=="broken","Corrupt primary recovers without rewriting damaged bytes");Reject(()=>RecoveryFiles.Backup(path,Validate),"Invalid primary never replaces last-good backup");Check(File.ReadAllBytes(RecoveryFiles.BackupPath(path)).SequenceEqual(original),"Last-good data survives failed backup");File.Delete(path);RecoveryFiles.Load(path,Validate,out fallback);Check(fallback,"Missing primary can recover from last-good");File.WriteAllText(RecoveryFiles.BackupPath(path),"bad");Reject(()=>RecoveryFiles.Load(path,Validate,out _),"Both invalid documents report explicit failure");}finally{Directory.Delete(root,true);}
var repaired=new EditorSession(new(){OriginalWidth=120,OriginalHeight=80});repaired.RequireSave();Check(repaired.Dirty&&!repaired.CanUndo,"Recovered document requests save without inventing an Undo action");repaired.MarkSaved();
for(int i=0;i<100;i++)RenderMetrics.Add(new(3840,2160,1,i,1));Check(RenderMetrics.Snapshot().Length==64,"Render diagnostics ring bounded to64 samples");
if(args.Length==2&&args[0]=="--benchmark"){
 var results=new List<object>();foreach(var size in new[]{(3840,2160),(7680,4320)}){var input=new byte[size.Item1*size.Item2*4];new Random(42).NextBytes(input);var timings=new List<double>();long before=GC.GetTotalAllocatedBytes();bool exact=true;for(int pass=0;pass<3;pass++){var l=new ImageLayout(new(0,0,size.Item1,size.Item2),new());var timer=System.Diagnostics.Stopwatch.StartNew();var output=ImageFidelity.CopyPixels(input,size.Item1,size.Item2,new(0,0,size.Item1,size.Item2),l);timer.Stop();timings.Add(timer.Elapsed.TotalMilliseconds);exact&=input.AsSpan().SequenceEqual(output);}results.Add(new{Width=size.Item1,Height=size.Item2,Passes=3,Milliseconds=timings,ExactPixels=exact,AllocatedBytes=GC.GetTotalAllocatedBytes()-before});}
 File.WriteAllText(args[1],JsonSerializer.Serialize(new{Version="1.20.0",Host=System.Runtime.InteropServices.RuntimeInformation.OSDescription,Runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,Scope="Pure native-pixel copy algorithm; not Windows WPF/GPU/capture or end-to-end memory acceptance",Results=results},new JsonSerializerOptions{WriteIndented=true}));
